                    ? 'bg-emerald-950/60 text-emerald-400 border-emerald-800/50'
                    : marginPercent >= 30
                    ? 'bg-cyan-950/60 text-cyan-300 border-cyan-800/50'
                    : 'bg-amber-950/60 text-amber-300 border-amber-800/50'
