                    currencySymbol="%"
                    decimals={1}
                    className="font-bold text-[8.5px]"
                  />
                </span>
              </div>
            </div>

            {/* Две симметричные колонки: Слева Цена и Себестоимость, Справа Прибыль и Склад */}
