      </div>

      {/* ========================================================================= */}
      {/* РАЗДЕЛ 04 · УПРАВЛЕНИЕ, БЫСТРЫЕ ДЕЙСТВИЯ И ТЕЛЕМЕТРИЯ                    */}
      {/* ========================================================================= */}
      <div
        className="p-2.5 sm:p-3 rounded-xl border border-white/10 bg-white/[0.02] flex items-center justify-between gap-2 flex-wrap font-mono"
