      >
        <div className="flex items-center gap-2 flex-wrap">
          {isProduct && onCreateOrder && (
            <CockpitButton
              size="sm"
              icon={ShoppingCart}
              accentColor={effectiveColor}
              onClick={() => onCreateOrder(item!)}
            >
              Создать заказ
            </CockpitButton>
          )}

          {isProduct && onLoadIntoCalculator && (
            <CockpitButton
              size="sm"
              icon={Calculator}
              accentColor={effectiveColor}
              onClick={() => onLoadIntoCalculator(item!)}
            >
              В калькулятор
            </CockpitButton>
          )}

          {hasStl && onOpenStlModal && isProduct && (
            <CockpitButton
              size="sm"
              icon={FileCode}
              accentColor={effectiveColor}
              onClick={() => onOpenStlModal(item!)}
            >
              3D Модель
            </CockpitButton>
          )}

          {isProduct && onOpenQuickEditModal && (
            <CockpitButton
              size="sm"
              icon={isAsm ? Wrench : Edit2}
              accentColor={effectiveColor}
              onClick={() => onOpenQuickEditModal(item!)}
            >
              {isAsm ? 'Спецификация сборки' : 'Полный редактор'}
            </CockpitButton>
          )}

          {isCol && onOpenAddVariantModal && (
            <CockpitButton
              size="sm"
              icon={Plus}
              accentColor={effectiveColor}
              onClick={() => onOpenAddVariantModal(row.collection)}
            >
              Добавить вариант
            </CockpitButton>
          )}

          {isCol && onOpenEditCollection && (
            <CockpitButton
              size="sm"
              icon={Edit2}
              accentColor={effectiveColor}
              onClick={() => onOpenEditCollection(row.collection)}
            >
              Настройки коллекции
            </CockpitButton>
          )}
        </div>
      </div>
    </div>
  );
}

