      >
        <div className="flex items-center gap-2 flex-wrap">
          {isProduct && onCreateOrder && (
            <CockpitButton
              size="sm"
              icon={ShoppingCart}
              accentColor={effectiveColor}
              onClick={() => onCreateOrder(item!)}
            >
              Создать заказ
            </CockpitButton>
          )}

          {isProduct && onLoadIntoCalculator && (
            <CockpitButton
              size="sm"
              icon={Calculator}
              accentColor={effectiveColor}
              onClick={() => onLoadIntoCalculator(item!)}
            >
              В калькулятор
            </CockpitButton>
          )}

          {hasStl && onOpenStlModal && isProduct && (
            <CockpitButton
              size="sm"
              icon={FileCode}
              accentColor={effectiveColor}
              onClick={() => onOpenStlModal(item!)}
            >
              3D Модель
            </CockpitButton>
          )}

          {(isAsm || isPart) && (onOpenEditAssembly || onOpenQuickEditModal) && (
            <CockpitButton
              size="sm"
              icon={Wrench}
              accentColor={effectiveColor}
              onClick={() => (onOpenEditAssembly || onOpenQuickEditModal)?.(item!)}
            >
              Спецификация сборки
            </CockpitButton>
          )}

          {isCol && onOpenAddVariantModal && (
            <CockpitButton
              size="sm"
              icon={Plus}
              accentColor={effectiveColor}
              onClick={() => onOpenAddVariantModal(row.collection)}
            >
              Добавить вариант
            </CockpitButton>
          )}

          {isCol && onOpenEditCollection && (
            <CockpitButton
              size="sm"
              icon={Edit2}
              accentColor={effectiveColor}
              onClick={() => onOpenEditCollection(row.collection)}
            >
              Настройки коллекции
            </CockpitButton>
          )}
        </div>

        {onClose && (
          <div className="flex items-center gap-2 shrink-0">
            <CockpitButton
              size="sm"
              icon={X}
              onClick={onClose}
            >
              Свернуть
            </CockpitButton>
          </div>
        )}
      </div>
    </div>
  );
}

